package org.flexlb.mockengine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.flexlb.engine.grpc.EngineRpcService;
import com.google.protobuf.ByteString;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

/** Golden operations are generated by the owning real Python cache, not Mock. */
class MockVitCacheReferenceTest {
    private static JsonNode reference() throws Exception {
        try (var stream = MockVitCacheReferenceTest.class.getResourceAsStream("/vit-cache-reference.json")) {
            assertNotNull(stream); return new ObjectMapper().readTree(stream);
        }
    }
    @Test void cpuEmbeddingAdmissionEvictionAndFragmentationMatchRealTraces() throws Exception {
        for (var trace : reference().path("embedding")) {
            try (var cache = new MockVitEmbeddingCache<String>(0, trace.path("capacity").longValue())) {
                for (int i = 0; i < trace.path("operations").size(); i++) {
                    var op = trace.path("operations").get(i); String key = op.get(1).asText();
                    switch (op.get(0).asText()) {
                        case "put" -> cache.put(key, key, List.of(new MockVitEmbeddingCache.Tensor(
                                new Object(), op.get(2).longValue(), 1, MockVitEmbeddingCache.Device.CPU)), key);
                        case "remove" -> cache.remove(key);
                        case "get" -> assertNotNull(cache.get(key));
                        default -> fail("unknown reference operation");
                    }
                    var expected = trace.path("expected").get(i); var stats = cache.stats();
                    assertEquals(expected.path("resident").longValue(), stats.get("embedding_bytes"), op.toString());
                    assertEquals(expected.path("used").longValue(), stats.get("cpu_pool_used_bytes"), op.toString());
                    assertEquals(expected.path("free").longValue(), stats.get("cpu_pool_free_bytes"), op.toString());
                    assertEquals(expected.path("largest").longValue(), stats.get("cpu_pool_largest_free_block_bytes"), op.toString());
                    var keys = cache.keys(MockVitEmbeddingCache.Device.CPU, 100).stream().sorted().toList();
                    assertEquals(expected.path("keys"), new ObjectMapper().valueToTree(keys), op.toString());
                }
            }
        }
    }
    private static MockVitImage.Result result(int hashes) {
        return new MockVitImage.Result(EngineRpcService.TensorPB.getDefaultInstance(),
                EngineRpcService.TensorPB.newBuilder().setInt32Data(ByteString.copyFrom(new byte[hashes * 4])).build(), hashes);
    }
    @Test void hashMetadataUnicodeChargeAndProbeRecencyMatchRealRuntime() throws Exception {
        var reference = reference(); var trace = reference.path("hashes");
        try (var cache = new MockVitHashCache(trace.path("capacity").longValue(), reference.path("hash_cache_accounting"))) {
            for (int i = 0; i < trace.path("operations").size(); i++) {
                var op = trace.path("operations").get(i); String key = op.get(1).asText();
                switch (op.get(0).asText()) {
                    case "put" -> cache.put(key, result(op.get(2).intValue()), "0".repeat(32));
                    case "probe" -> assertNotNull(cache.peek(key));
                    case "consume" -> assertNotNull(cache.consume(key, "0".repeat(32)));
                    default -> fail("unknown reference operation");
                }
                var expected = trace.path("expected").get(i);
                assertEquals(expected.path("resident").longValue(), cache.stats().get("hash_bytes"), op.toString());
                assertEquals(expected.path("keys"), new ObjectMapper().valueToTree(cache.keys(100)), op.toString());
            }
            cache.put("generation", result(1), "0".repeat(32));
            var before = cache.keys(100);
            assertNull(cache.consume("generation", "wrong-generation"));
            assertEquals(before, cache.keys(100));
        }
    }
}
